const siteUrl = $env.WEBSITE_URL || 'https://example.com';
const pagesToAudit = ($env.SEO_AUDIT_PAGES || '').split(',').filter(Boolean);

// If no specific pages, audit homepage + key pages
const pages = pagesToAudit.length > 0 ? pagesToAudit : [
  siteUrl,
  `${siteUrl}/services`,
  `${siteUrl}/blog`,
  `${siteUrl}/contact`
];

return { json: { site_url: siteUrl, pages } };

const pageSpeed = $('PageSpeed Home').item.json;
const indexedPages = $('Check Indexed Pages').item.json;
const config = $('Configure Pages').item.json;

// Extract Lighthouse scores
const lighthouse = pageSpeed?.lighthouseResult;
const categories = lighthouse?.categories || {};

const auditData = {
  site_url: config.site_url,
  audit_date: new Date().toISOString(),
  scores: {
    performance: Math.round((categories.performance?.score || 0) * 100),
    seo: Math.round((categories.seo?.score || 0) * 100),
    accessibility: Math.round((categories.accessibility?.score || 0) * 100)
  },
  page_load_time: lighthouse?.audits?.['speed-index']?.numericValue || 0,
  indexed_pages: indexedPages?.search_information?.total_results || 0,
  top_indexed: (indexedPages?.organic_results || []).slice(0, 10).map(r => ({
    title: r.title,
    url: r.link,
    position: r.position
  })),
  critical_issues: [],
  warnings: []
};

// Check for critical issues
if (auditData.scores.seo < 80) auditData.critical_issues.push('Score SEO < 80');
if (auditData.scores.performance < 50) auditData.critical_issues.push('Performance critique < 50');
if (auditData.page_load_time > 5000) auditData.critical_issues.push('Temps de chargement > 5s');

// Extract specific audit failures
const audits = lighthouse?.audits || {};
for (const [key, audit] of Object.entries(audits)) {
  if (audit.score === 0 && audit.title) {
    auditData.critical_issues.push(audit.title);
  } else if (audit.score !== null && audit.score < 0.5 && audit.title) {
    auditData.warnings.push(audit.title);
  }
}

return { json: auditData };

