const auditData = $('Process Audit Data').item.json;
const aiResponse = $input.item.json.message.content;
let report;
try { report = JSON.parse(aiResponse); } catch (e) { report = { error: 'Parse failed' }; }

return {
  json: {
    report_type: 'seo_audit',
    generated_at: new Date().toISOString(),
    agent_id: 'seo-specialist',
    workflow_id: 'WF-SEO-AUDIT',
    raw_scores: auditData.scores,
    indexed_pages: auditData.indexed_pages,
    report
  }
};
